BEGIN;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES
 ('14200000-0000-4000-8000-000000000001','vat-review-owner@example.test','{"_invite_provisioned":true}'),
 ('14200000-0000-4000-8000-000000000002','vat-review-foreign@example.test','{"_invite_provisioned":true}');
CREATE TEMP TABLE review_company AS SELECT (public.provision_company_atomic('14200000-0000-4000-8000-000000000001','{"name":"VAT review fixture","slug":"vat-review-142","domain":"vat-review-142.example.test"}')->>'id')::uuid id;
SELECT public.provision_company_atomic('14200000-0000-4000-8000-000000000002','{"name":"Foreign VAT fixture","slug":"foreign-vat-142","domain":"foreign-vat-142.example.test"}');
UPDATE public.users SET must_change_password=false WHERE auth_user_id IN('14200000-0000-4000-8000-000000000001','14200000-0000-4000-8000-000000000002');
CREATE TEMP TABLE review_cases(id uuid DEFAULT gen_random_uuid(),label text,issue_date date DEFAULT '2062-01-01',rate numeric DEFAULT 15);
INSERT INTO review_cases(label) VALUES('recoverable'),('nonrecoverable'),('audit'),('drift'),('unprocessed'),('reversed'),('bad identity'),('bad payload'),('bad audit');
INSERT INTO review_cases(label,issue_date) VALUES('closed accounting','2062-02-01'),('closed VAT','2062-03-01');
INSERT INTO review_cases(label,rate) VALUES('zero',0);
INSERT INTO public.expenses(id,tenant_id,expense_type,amount,expense_date,created_by) SELECT c.id,t.id,'fuel',100,c.issue_date,'14200000-0000-4000-8000-000000000001' FROM review_cases c,review_company t;
-- Corrupt only new synthetic evidence before insertion, simulating malformed imports
-- while retaining the production immutable-event and approved-expense guards.
CREATE FUNCTION pg_temp.corrupt_review_event() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF EXISTS(SELECT 1 FROM review_cases WHERE id=NEW.source_id AND label='bad identity') THEN NEW.payload:=NEW.payload||jsonb_build_object('expense_id','14200000-0000-4000-8000-000000000099');END IF;
 IF EXISTS(SELECT 1 FROM review_cases WHERE id=NEW.source_id AND label='bad payload') THEN NEW.payload:=NEW.payload||jsonb_build_object('amount','malformed imported amount');END IF;
 RETURN NEW;END $$;
CREATE TRIGGER synthetic_bad_event BEFORE INSERT ON public.financial_events FOR EACH ROW EXECUTE FUNCTION pg_temp.corrupt_review_event();
CREATE FUNCTION pg_temp.corrupt_review_audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF NEW.action='expense_approved' AND EXISTS(SELECT 1 FROM review_cases WHERE id=NEW.entity_id AND label='bad audit') THEN NEW.new_values:=NEW.new_values||jsonb_build_object('vat_amount','malformed imported VAT');END IF;
 RETURN NEW;END $$;
CREATE TRIGGER synthetic_bad_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.corrupt_review_audit();
SELECT public.approve_expense_atomic(t.id,c.id,c.rate,'pending_review','14200000-0000-4000-8000-000000000001') FROM review_cases c,review_company t;
DROP TRIGGER synthetic_bad_event ON public.financial_events;
DROP TRIGGER synthetic_bad_audit ON public.audit_log;
SELECT public.dispatch_expense_approved(fe) FROM public.financial_events fe JOIN review_cases c ON c.id=fe.source_id;
UPDATE public.financial_events fe SET processing_status='processed',processed_at=now() FROM review_cases c WHERE fe.source_id=c.id;
CREATE TEMP TABLE review_inputs AS SELECT c.label,l.id FROM review_cases c JOIN public.vat_input_ledger l ON l.source_entity_id=c.id;
GRANT SELECT ON review_inputs,review_cases,review_company TO authenticated,service_role;
UPDATE public.accounting_periods SET status='closed' WHERE tenant_id=(SELECT id FROM review_company) AND period_year=2062 AND period_month=2;
INSERT INTO public.vat_periods(tenant_id,period_year,period_month,status) SELECT id,2062,3,'closed' FROM review_company;
UPDATE public.vat_input_ledger SET vat_base_amount=101 WHERE id=(SELECT id FROM review_inputs WHERE label='drift');
UPDATE public.financial_events fe SET processing_status='pending',processed_at=NULL FROM review_cases c WHERE c.label='unprocessed' AND fe.source_id=c.id;
SELECT public.reverse_journal_entry(t.id,j.id,'Synthetic reversal before classification',NULL,'2062-01-02','14200000-0000-4000-8000-000000000001') FROM review_cases c,review_company t JOIN public.journal_entries j ON j.tenant_id=t.id WHERE c.label='reversed' AND j.source_entity_id=c.id;
CREATE TEMP TABLE imported_review AS SELECT gen_random_uuid() id;
INSERT INTO public.vat_input_ledger(id,tenant_id,period_year,period_month,invoice_ref,invoice_date,vat_base_amount,vat_rate,vat_amount,vat_recoverability) SELECT i.id,t.id,2062,1,'IMPORTED-UNKNOWN','2062-01-01',100,15,15,'pending_review' FROM imported_review i,review_company t;
GRANT SELECT ON imported_review TO authenticated;
SELECT ok(NOT has_function_privilege('service_role','public.resolve_my_vat_review(uuid,text)','execute'),'service API cannot bypass the caller VAT workflow');
SELECT ok(NOT has_schema_privilege('authenticated','vat_review_private','usage'),'private resolution evidence is not browser exposed');
SELECT ok(NOT has_table_privilege('authenticated','public.vat_input_ledger','INSERT'),'browser cannot invent a direct input VAT claim');
SELECT ok(NOT has_any_column_privilege('authenticated','public.vat_input_ledger','UPDATE'),'legacy column grants cannot alter pending VAT evidence');
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14200000-0000-4000-8000-000000000001","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='recoverable'),'recoverable')$$,'42501','VAT review access denied','low-assurance owner cannot classify VAT');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14200000-0000-4000-8000-000000000002","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='recoverable'),'recoverable')$$,'P0001','VAT005: review item not found','foreign tenant cannot resolve the source');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"14200000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='recoverable'),'anything')$$,'22023','Invalid VAT classification','unsupported classification fails before posting');
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM imported_review),'recoverable')$$,'P0001','VAT007: source posting requires finance review','imported input without source is held, never given a fabricated journal');
SELECT throws_ok(format('SELECT public.resolve_my_vat_review(%L,%L)',id,'recoverable'),'P0001','VAT007: source posting requires finance review',label||' source is held for finance review') FROM review_inputs WHERE label IN('drift','unprocessed','reversed','bad identity','bad payload','bad audit');
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='closed accounting'),'recoverable')$$,'P0001','ACC001: source accounting period is closed','classification cannot post into closed accounting period');
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='closed VAT'),'non_recoverable')$$,'P0001','VAT001: source VAT period is closed','even nonrecoverable classification cannot rewrite closed VAT period');
SELECT lives_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='recoverable'),'recoverable')$$,'recoverable classification and adjusting journal commit');
SELECT is((SELECT vat_recoverability FROM public.vat_input_ledger WHERE id=(SELECT id FROM review_inputs WHERE label='recoverable')),'recoverable','claim is final after successful posting');
SELECT is((SELECT count(*)::int FROM public.journal_entries WHERE source_entity_type='vat_input_review' AND source_entity_id=(SELECT id FROM review_inputs WHERE label='recoverable')),1,'one adjustment journal per classified input');
SELECT is((SELECT sum(l.debit_amount-l.credit_amount) FROM public.journal_entries j JOIN public.journal_entry_lines l ON l.journal_entry_id=j.id JOIN public.chart_of_accounts a ON a.id=l.account_id WHERE j.tenant_id=(SELECT id FROM review_company) AND j.source_entity_type='vat_input_review' AND j.source_entity_id=(SELECT id FROM review_inputs WHERE label='recoverable') AND a.account_code='2600'),15::numeric,'claim has matching VAT receivable debit');
SELECT is((SELECT sum(l.credit_amount-l.debit_amount) FROM public.journal_entries j JOIN public.journal_entry_lines l ON l.journal_entry_id=j.id JOIN public.chart_of_accounts a ON a.id=l.account_id WHERE j.tenant_id=(SELECT id FROM review_company) AND j.source_entity_type='vat_input_review' AND j.source_entity_id=(SELECT id FROM review_inputs WHERE label='recoverable') AND a.account_code='5000'),15::numeric,'same adjustment removes VAT from actual expense account');
SELECT is((SELECT sum(l.debit_amount-l.credit_amount) FROM public.journal_entries j JOIN public.journal_entry_lines l ON l.journal_entry_id=j.id JOIN public.chart_of_accounts a ON a.id=l.account_id WHERE j.tenant_id=(SELECT id FROM review_company) AND ((j.source_entity_type='expense' AND j.source_entity_id=(SELECT id FROM review_cases WHERE label='recoverable')) OR (j.source_entity_type='vat_input_review' AND j.source_entity_id=(SELECT id FROM review_inputs WHERE label='recoverable'))) AND a.account_code='5000'),100::numeric,'net source expense becomes100 while original115 remains immutable');
SELECT is((SELECT vat_recoverability FROM public.expenses WHERE id=(SELECT id FROM review_cases WHERE label='recoverable')),'pending_review','approved source retains its original classification snapshot');
SELECT is((SELECT count(*)::int FROM public.audit_log WHERE entity_id=(SELECT id FROM review_inputs WHERE label='recoverable') AND action='vat_review_item_resolved'),1,'one source-linked audit for successful decision');
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='recoverable'),'recoverable')$$,'P0001','VAT004: classification is already final','retry cannot post VAT twice');
SELECT lives_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='nonrecoverable'),'non_recoverable')$$,'nonrecoverable decision preserves gross expense');
SELECT is((SELECT count(*)::int FROM public.journal_entries WHERE source_entity_type='vat_input_review' AND source_entity_id=(SELECT id FROM review_inputs WHERE label='nonrecoverable')),0,'no unnecessary adjustment for nonrecoverable VAT');
SELECT lives_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='zero'),'recoverable')$$,'zero VAT can be reviewed without an empty posting');
SELECT is((SELECT count(*)::int FROM public.journal_entries WHERE source_entity_type='vat_input_review' AND source_entity_id=(SELECT id FROM review_inputs WHERE label='zero')),0,'zero VAT produces no forbidden zero-value lines');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM vat_review_private.resolutions),3,'all three final classifications retain private immutable lineage');
SELECT throws_ok($$UPDATE vat_review_private.resolutions SET classification='non_recoverable' WHERE input_id=(SELECT id FROM review_inputs WHERE label='recoverable')$$,'55000','VAT_REVIEW_IMMUTABLE: preserve the recorded VAT resolution','even owner repairs require separate explicit review of immutable resolution');
SELECT throws_ok($$DELETE FROM public.vat_input_ledger WHERE id=(SELECT id FROM review_inputs WHERE label='recoverable')$$,'55000','VAT_REVIEW_IMMUTABLE: preserve the recorded VAT resolution','classified input cannot disappear independently');
SELECT throws_ok($$INSERT INTO public.vat_input_ledger(tenant_id,period_year,period_month,invoice_ref,invoice_date,vat_amount,source_entity_type,source_entity_id) SELECT t.id,2062,1,'duplicate','2062-01-01',15,'expense',c.id FROM review_company t,review_cases c WHERE c.label='recoverable'$$,'55000','VAT_REVIEW_IMMUTABLE: preserve the recorded VAT resolution','duplicate source cannot create a second claim');
SELECT throws_ok($$SELECT public.reverse_journal_entry(t.id,j.id,'Forbidden independent reversal',NULL,'2062-01-03') FROM review_company t JOIN public.journal_entries j ON j.tenant_id=t.id WHERE j.source_entity_type='vat_input_review' AND j.source_entity_id=(SELECT id FROM review_inputs WHERE label='recoverable')$$,'55000','VAT_REVIEW_IMMUTABLE: preserve the recorded VAT resolution','adjustment cannot be reversed independently from VAT ledger');
SELECT throws_ok($$SELECT public.reverse_journal_entry(t.id,j.id,'Forbidden original reversal',NULL,'2062-01-03') FROM review_company t JOIN public.journal_entries j ON j.tenant_id=t.id WHERE j.source_entity_type='expense' AND j.source_entity_id=(SELECT id FROM review_cases WHERE label='recoverable')$$,'55000','VAT_REVIEW_IMMUTABLE: preserve the recorded VAT resolution','original classified source cannot be reversed independently');
SELECT throws_ok($$UPDATE public.journal_entry_lines SET description='mutation' WHERE journal_entry_id=(SELECT adjustment_entry_id FROM vat_review_private.resolutions WHERE input_id=(SELECT id FROM review_inputs WHERE label='recoverable'))$$,'55000','VAT_REVIEW_IMMUTABLE: preserve the recorded VAT resolution','linked posted lines remain immutable');
CREATE FUNCTION pg_temp.reject_vat_review_audit() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.action='vat_review_item_resolved' THEN RAISE EXCEPTION 'Synthetic VAT audit failure';END IF;RETURN NEW;END $$;
CREATE TRIGGER test_vat_review_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_vat_review_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='audit'),'recoverable')$$,'P0001','Synthetic VAT audit failure','audit failure rolls back claim and posted adjustment');
SELECT is((SELECT vat_recoverability FROM public.vat_input_ledger WHERE id=(SELECT id FROM review_inputs WHERE label='audit')),'pending_review','failed decision remains pending');
SELECT is((SELECT count(*)::int FROM public.journal_entries WHERE source_entity_type='vat_input_review' AND source_entity_id=(SELECT id FROM review_inputs WHERE label='audit')),0,'failed audit leaves no posted financial adjustment');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM vat_review_private.resolutions WHERE input_id=(SELECT id FROM review_inputs WHERE label='audit')),0,'failed audit leaves no private resolution');
DROP TRIGGER test_vat_review_audit ON public.audit_log;
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='audit'),'recoverable')$$,'fresh retry after audit recovery commits once');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT throws_ok($$SELECT public.resolve_my_vat_review((SELECT id FROM review_inputs WHERE label='drift'),'recoverable')$$,'42501',NULL,'service-role execution is denied even with caller-like claims');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.resolve_my_vat_review(NULL,'recoverable')$$,'42501',NULL,'anonymous resolution execution denied');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
